+package com.example.customers.domain;
+
+import java.io.Serializable;
+import java.text.Normalizer;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * The criteria the customer list is narrowed by. Understood by
+ * {@link CustomerRepository}, so that both the page query and the count query
+ * see the same restriction and the grid never has to hold more than one page.
+ *
+ * <p>A customer matches when it satisfies both parts:
+ *
+ * <ul>
+ * <li><b>name</b> &mdash; every whitespace-separated term of {@code name} must
+ * occur in the first name or in the last name. Case and accents are ignored on
+ * both sides, so {@code makinen} matches {@code Mäkinen} and vice versa. A blank
+ * name matches everything.</li>
+ * <li><b>statuses</b> &mdash; the customer's status must be one of
+ * {@code statuses}. An empty set matches everything.</li>
+ * </ul>
+ *
+ * @param name     the raw text typed into the name filter; never {@code null}
+ * @param statuses the selected statuses; never {@code null}, empty means "any"
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) implements Serializable {
+
+    /** Matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** {@code true} when this filter lets every customer through. */
+    public boolean isEmpty() {
+        return statuses.isEmpty() && nameTerms().isEmpty();
+    }
+
+    /**
+     * The name filter split into normalized terms; empty when no name was
+     * entered. Leading, trailing and repeated whitespace is not significant.
+     */
+    public List<String> nameTerms() {
+        String normalized = normalize(name).trim();
+        return normalized.isEmpty() ? List.of() : List.of(WHITESPACE.split(normalized));
+    }
+
+    /**
+     * This filter as a predicate. The name terms are normalized once, not once
+     * per customer.
+     */
+    public Predicate<Customer> asPredicate() {
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> selected = statuses;
+        if (terms.isEmpty() && selected.isEmpty()) {
+            return customer -> true;
+        }
+        return customer -> (selected.isEmpty() || selected.contains(customer.status()))
+                && matchesName(customer, terms);
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        for (String term : terms) {
+            if (!firstName.contains(term) && !lastName.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /**
+     * Folds away case and accents, so that {@code Joséphine}, {@code JOSEPHINE}
+     * and {@code josephine} all compare equal.
+     */
+    static String normalize(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
