+                "Typing eight letters ran " + queryLog.countQueries().size()
+                        + " count queries; it must be debounced");
+        assertTrue(queryLog.rowsFetched() <= 200,
+                "Filtering pulled " + queryLog.rowsFetched() + " rows over");
+    }
+
+    @Test
+    void openingAFilteredUrlAppliesAndShowsTheFilter() {
+        page.navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
+        awaitSummary(SUMMARY.pattern());
+
+        PlaywrightAssertions.assertThat(nameField()).hasValue("vir");
+        assertEquals(List.of("ACTIVE", "CLOSED"), selectedStatuses());
+        assertTrue(Integer.parseInt(summaryText().split(" ")[1]) < 500,
+                "The filter from the URL must narrow the list");
+    }
+
+    @Test
+    void clearingTheFilterEmptiesTheAddressBar() {
+        page.navigate(getUrl() + "/?name=vir&status=ACTIVE");
+        awaitSummary(SUMMARY.pattern());
+
+        nameField().fill("");
+        awaitUrl(url -> !url.contains("name="));
+        assertTrue(page.url().contains("status=ACTIVE"),
+                "Clearing the name must leave the status alone, was " + page.url());
+
+        toggleStatus(CustomerStatus.ACTIVE); // deselects it again
+        awaitUrl(url -> !url.contains("status="));
+
+        assertTrue(page.url().endsWith("/"),
+                "An empty filter must leave no query parameters, was " + page.url());
+        awaitSummary("Showing 500 of 500");
+    }
+
+    @Test
+    void statusSelectionReachesTheAddressBarInDeclarationOrder() {
+        awaitSummary("Showing 500 of 500");
+
+        toggleStatus(CustomerStatus.CLOSED);
+        awaitUrl(url -> url.contains("status=CLOSED"));
+        toggleStatus(CustomerStatus.ACTIVE);
+        awaitUrl(url -> url.contains("status=ACTIVE,CLOSED"));
+
+        assertTrue(page.url().endsWith("/?status=ACTIVE,CLOSED"),
+                "Statuses belong in the URL in declaration order, was " + page.url());
+    }
+
+    // --- helpers -----------------------------------------------------------
+
+    private Locator nameField() {
+        return page.locator("vaadin-text-field input");
+    }
+
+    /** Selects the status, or deselects it if it was already selected. */
+    private void toggleStatus(CustomerStatus status) {
+        page.locator("vaadin-multi-select-combo-box input").click();
+        // The overlay lists the statuses in declaration order.
+        page.locator("vaadin-multi-select-combo-box-item").nth(status.ordinal()).click();
+        page.keyboard().press("Escape");
+    }
+
+    @SuppressWarnings("unchecked")
+    private List<String> selectedStatuses() {
+        Object labels = page.locator("vaadin-multi-select-combo-box")
+                .evaluate("el => el.selectedItems.map(item => item.label)");
+        return ((List<Object>) labels).stream().map(String::valueOf).toList();
+    }
+
+    private String summaryText() {
+        return page.getByText(SUMMARY).first().innerText().trim();
+    }
+
+    private List<String> rowsOnScreen() {
+        return page.locator("vaadin-grid-cell-content")
+                .allInnerTexts().stream()
+                .map(String::trim)
+                .filter(text -> text.endsWith("aaltonen") || text.equals("Aaltonen"))
+                .toList();
+    }
+
+    private void awaitSummary(String expected) {
+        PlaywrightAssertions.assertThat(page.getByText(SUMMARY).first())
+                .hasText(Pattern.compile(expected));
+    }
+
+    private void awaitSummaryChange(String previous) {
+        PlaywrightAssertions.assertThat(page.getByText(SUMMARY).first())
+                .not().hasText(previous);
+    }
+
+    private void awaitUrl(java.util.function.Predicate<String> condition) {
+        page.waitForCondition(() -> condition.test(page.url()));
+    }
+}
