+/** The matching rules, without a UI around them. */
+class CustomerFilterTest {
+
+    private static final Customer ADA = new Customer(
+            1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer JOSEPHINE = new Customer(
+            2, "Joséphine", "Mäkinen", "jo@example.com", "France", CustomerStatus.CLOSED);
+
+    @Test
+    void anEmptyFilterMatchesEverybody() {
+        assertTrue(CustomerFilter.EMPTY.isEmpty());
+        assertTrue(CustomerFilter.EMPTY.asPredicate().test(ADA));
+        assertTrue(CustomerFilter.EMPTY.asPredicate().test(JOSEPHINE));
+        assertTrue(new CustomerFilter("   ", Set.of()).isEmpty(), "Blank is no filter at all");
+    }
+
+    @Test
+    void everyTermMustMatchEitherName() {
+        assertTrue(matches("ada aal", ADA));
+        assertTrue(matches("aal ada", ADA), "Order must not matter");
+        assertTrue(matches("  ada   aal  ", ADA), "Whitespace must not matter");
+        assertFalse(matches("ada virtanen", ADA), "Every term must match");
+    }
+
+    @Test
+    void caseAndAccentsAreIgnoredInBothDirections() {
+        assertTrue(matches("makinen", JOSEPHINE));
+        assertTrue(matches("MAKINEN", JOSEPHINE));
+        assertTrue(matches("mäkinen", JOSEPHINE));
+        assertTrue(matches("MÄKINEN", JOSEPHINE));
+        assertTrue(matches("josephine", JOSEPHINE));
+        assertTrue(matches("Joséphine", JOSEPHINE));
+    }
+
+    @Test
+    void statusesAreCombinedWithOr() {
+        assertTrue(status(CustomerStatus.ACTIVE).asPredicate().test(ADA));
+        assertFalse(status(CustomerStatus.ACTIVE).asPredicate().test(JOSEPHINE));
+        assertTrue(status(CustomerStatus.ACTIVE, CustomerStatus.CLOSED).asPredicate().test(JOSEPHINE));
+    }
+
+    @Test
+    void bothPartsMustMatch() {
+        CustomerFilter filter = new CustomerFilter("mak", Set.of(CustomerStatus.ACTIVE));
+        assertFalse(filter.asPredicate().test(JOSEPHINE), "Right name, wrong status");
+        assertFalse(filter.asPredicate().test(ADA), "Right status, wrong name");
+    }
+
+    @Test
+    void termsAreNormalizedOnce() {
+        assertEquals(List.of("ada", "aal"), new CustomerFilter(" Ada  AAL ", Set.of()).nameTerms());
+        assertEquals(List.of(), new CustomerFilter(" \t ", Set.of()).nameTerms());
+    }
+
+    @Test
+    void nullsAreTreatedAsNoFilter() {
+        assertTrue(new CustomerFilter(null, null).isEmpty());
+    }
+
+    private static boolean matches(String name, Customer customer) {
+        return new CustomerFilter(name, Set.of()).asPredicate().test(customer);
+    }
+
+    private static CustomerFilter status(CustomerStatus... statuses) {
+        return new CustomerFilter("", Set.of(statuses));
+    }
+}
