+package com.example.customers.ui;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+import java.util.LinkedHashSet;
+import java.util.Set;
+
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerStatus;
+
+import org.junit.jupiter.api.Test;
+
+/** What the filter looks like in the address bar. */
+class CustomerListViewUrlTest {
+
+    @Test
+    void anEmptyFilterLeavesNoParameters() {
+        assertEquals(".", CustomerListView.toLocation(CustomerFilter.EMPTY));
+        assertEquals(".", CustomerListView.toLocation(new CustomerFilter("  ", Set.of())));
+    }
+
+    @Test
+    void nameAndStatusesAreBothCarried() {
+        assertEquals("?name=vir", CustomerListView.toLocation(
+                new CustomerFilter("vir", Set.of())));
+        assertEquals("?status=ACTIVE", CustomerListView.toLocation(
+                new CustomerFilter("", Set.of(CustomerStatus.ACTIVE))));
+        assertEquals("?name=vir&status=ACTIVE,CLOSED", CustomerListView.toLocation(
+                new CustomerFilter("vir", Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE))));
+    }
+
+    @Test
+    void statusesAreListedInDeclarationOrderWhateverOrderTheyWerePicked() {
+        Set<CustomerStatus> pickedBackwards = new LinkedHashSet<>();
+        pickedBackwards.add(CustomerStatus.CLOSED);
+        pickedBackwards.add(CustomerStatus.PENDING);
+        pickedBackwards.add(CustomerStatus.ACTIVE);
+
+        assertEquals("?status=ACTIVE,PENDING,CLOSED",
+                CustomerListView.toLocation(new CustomerFilter("", pickedBackwards)));
+    }
+
+    @Test
+    void aNameIsEscapedAndTrimmed() {
+        assertEquals("?name=ada%20aal", CustomerListView.toLocation(
+                new CustomerFilter("  ada aal ", Set.of())));
+        assertEquals("?name=m%C3%A4kinen", CustomerListView.toLocation(
+                new CustomerFilter("mäkinen", Set.of())));
+    }
+}
